ctDetailType": if(payload.product.productDetailType != null and payload.product.productDetailType != "")payload.product.productDetailType else "", "productClass": payload.product.productClass, "agreementStatus": payload.product.agreementStatus, //"effectiveDate": payload.product.effectiveDate, //"expirationDate": payload.product.expirationDate, "formNumber": payload.product.formNumber, "isCombo": if(payload.product.isCombo != null and payload.product.isCombo != "")payload.product.isCombo as Boolean else "", "reportedCustomerCost": if(payload.product.reportedCustomerCost != null and payload.product.reportedCustomerCost != "")payload.product.reportedCustomerCost as Number else "", //"salesTax": payload.product.salesTax, "deductible": payload.product.deductibleBase as Number, "reducedDeductible": if(payload.product.deductibleReduced != null and payload.product.deductibleReduced != "")payload.product.deductibleReduced as Number else "", "serviceInterval": if(payload.product.serviceInterval != null and payload.product.serviceInterval != "")payload.product.serviceInterval as Number else "" , "numberOfServices": payload.product.numberOfServices, "systemPin": payload.product.systemPin, "coverage": payload.product.coverage, "termMonths": payload.product.termMonths, "termDistance": payload.product.termDistance, "autoRenew": if(payload.product.autoRenew != null and payload.product.autoRenew != "")payload.product.autoRenew else "N", "optionalCoverages": if(payload.product.optionalCoverages != null and payload.product.optionalCoverages != "")(payload.product.optionalCoverages map { "coverageType": $.coverageType, "coverageAmount": $.coverageAmount }) else "" }], "fillers": [], "holder" : {
//"memberNumber": payload.holder.memberNumber, //"salutation": payload.holder, "customerFirstName": payload.holder.customerFirstName, "customerMiddleName": payload.holder.customerMiddleName, "customerLastName": payload.holder.customerLastName, "customerAddress1": payload.holder.customerAddress1, //"customerAddress2": payload.holder.customerAddress2, "customerCity": payload.holder.customerCity, "customerStateCode": payload.holder.customerStateCode, "customerPostalCode": payload.holder.customerPostalCode, "customerCountryCode": payload.holder.customerCountryCode, "customerHomePhoneNumber": payload.holder.customerHomePhoneNumber, "customerWorkPhoneNumber": payload.holder.customerWorkPhoneNumber, "customerMobilePhoneNumber": payload.holder.customerMobilePhoneNumber, "customerEveningPhoneNumber": payload.holder.customerEveningPhoneNumber, "customerEmail": payload.holder.customerEmail, "coBuyerFirstName": payload.holder.coBuyerFirstName, "coBuyerMiddleName": payload.holder.coBuyerMiddleName, "coBuyerLastName": payload.holder.coBuyerLastName, "coBuyerAddress1": payload.holder.coBuyerAddress1, "coBuyerAddress2": payload.holder.coBuyerAddress2, "coBuyerCity": payload.holder.coBuyerCity, "coBuyerStateCode": payload.holder.coBuyerStateCode, "coBuyerPostalCode": payload.holder.coBuyerPostalCode, "coBuyerCountryCode": payload.holder.coBuyerCountryCode, "coBuyerHomePhoneNumber": payload.holder.coBuyerHomePhoneNumber, "coBuyerWorkPhoneNumber": payload.holder.coBuyerWorkPhoneNumber, "coBuyerMobilePhoneNumber": payload.holder.coBuyerMobilePhoneNumber, "coBuyerEmail": payload.holder.coBuyerEmail }, "financing" : { "lienholderName": payload.financing.lienholderName, "lienholderAddress1": payload.financing.lienholderAddress1, "lienholderAddress2": payload.financing.lienholderAddress2, "lienholderCity": payload.financing.lienholderCity, "lienholderState": payload.financing.lienholderState, "lienholderPostalCode": payload.financing.lienholderPostalCode, "lienholderPhoneNumber": payload.financing.lienholderPhoneNumber, "lienholderNumber": payload.financing.lienholderNumber, "lienholderAccountNumber": payload.financing.lienholderAccountNumber, "financeType": if(payload.financing.financeType == "Cash")"C" else if(payload.financing.financeType == "Loan")"L" else if(payload.financing.financeType == "Lease")"LE" else if(payload.financing.financeType == "OtherLoan")"LO" else if(payload.financing.financeType == "Balloon")"BL" else "F", "baloonResidualValue": if(payload.financing.baloonResidualValue != null and payload.financing.baloonResidualValue != "")payload.financing.baloonResidualValue as Number else "", //"financedAmount": payload.financing.financedAmount, "annualPercentageRate": payload.financing.annualPercentageRate, "loanTotalPayment": payload.financing.loanTotalPayment, //"financeTermMonths": payload.financing.financeTermMonths, "numberOfAdvPayments": payload.financing.numberOfAdvPayments, "numberOfSkipPayments": if(payload.financing.numberOfSkipPayments != null and payload.financing.numberOfSkipPayments != "")payload.financing.numberOfSkipPayments as Number else "", "msrp": payload.financing.msrp, "bookValue": if(payload.financing.bookValue != null and payload.financing.bookValue != null)payload.financing.bookValue as Number else "", //"interestStartDate": payload.financing.interestStartDate, "dateOfFirstPayment": payload.financing.dateOfFirstPayment, "loanNumber": payload.financing.loanNumber, //"gapIdNumber": payload.financing.gapIdNumber, //"leaseCapAmount": payload.financing.leaseCapAmount, //"period": payload.financing.period, "startDate": payload.product.effectiveDate, //"endDate": payload.financing.endDate, "grossCapCost":if(payload.financing.grossCapCost != null and payload.financing.grossCapCost != "") payload.financing.grossCapCost as Number else "", "totalAllowableMilesContract": if(payload.financing.totalAllowableMilesContract != null and payload.financing.totalAllowableMilesContract != "")payload.financing.totalAllowableMilesContract as Number else "", "scheduledTerminationDate": payload.financing.scheduledTerminationDate, "loanMonthlyPayment": if(payload.financing.loanMonthlyPayment != null and payload.financing.loanMonthlyPayment != "")payload.financing.loanMonthlyPayment as Number else "", "paymentDueDay":payload.product.paymentDueDay, "installmentDownPayment": payload.financing.installmentDownPayment default "", "installmentAmount": payload.financing.installmentAmount default "", "installmentPaymentFrequency":payload.financing.installmentPaymentFrequency default "", "installmentPaymentTerm":payload.financing.installmentPaymentTerm }
